  class: net.officefloor.hq.app.period.RespondWithGeneratedPeriods
  govern: [ transaction ]
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Adds each person's open figure at the end of the old year's last period to their opening balance for the new year's
 * first period: the due now of their claims that count then, whose due-by falls in a period of the old year, and that
 * were OPEN or PENDING at that period's end by their status log (a person with none gets no line). Only a first period
 * this rollover generated gets openings, so rolling over again does not carry twice. Then audits the
 * rollover with how many periods the generator made, keeping it as the sheet's last so it can be undone.
 */
public class CarryOpenings {
    public void carry(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @Val RolloverYear year, @Val Integer made, Periods periods, Claims claims, People people, Rates rates,
            Settings settings, SheetClock clock, Rollovers rollovers, Audit audit) {
        List<Rollovers.Opening> set = new ArrayList<>();
        List<Period> old = periods.list(sheet).stream()
                .filter((p) -> !LocalDate.parse(p.from()).isBefore(year.from())
                        && !LocalDate.parse(p.from()).isAfter(year.to()))
                .toList();
        LocalDate end = old.stream().map((p) -> LocalDate.parse(p.to())).max(Comparator.naturalOrder()).orElseThrow();
        Period first = periods.on(sheet, year.next());
        if (first != null && !year.before().contains(first.name())) {
            List<Rate> sheetRates = rates.list(sheet);
            Dated floor = settings.floor(sheet);
            Late late = settings.late(sheet, clock.today(sheet));
            Map<Long, BigDecimal> open = new LinkedHashMap<>();
            List<Claim> sheetClaims = claims.list(sheet);
            for (Person person : people.list(sheet)) {
                for (Claim claim : sheetClaims) {
                    if (claim.person() != person.id()) {
                        continue;
                    }
                    LocalDate dueBy = LocalDate.parse(claim.dueBy());
                    boolean inOld = old.stream().anyMatch((p) -> !dueBy.isBefore(LocalDate.parse(p.from()))
                            && !dueBy.isAfter(LocalDate.parse(p.to())));
                    ClaimStatus then = claim.statusOn(end);
                    if (!inOld || (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING)
                            || !person.countsOn(claim, end)) {
                        continue;
                    }
                    BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
                    if (due != null) {
                        open.merge(person.id(), due, BigDecimal::add);
                    }
                }
                BigDecimal amount = open.get(person.id());
                if (amount != null && amount.signum() != 0) {
                    periods.addOpening(sheet, first.name(), person.id(), amount);
                    set.add(new Rollovers.Opening(first.name(), person.id(), amount));
                    audit.record("OPENING_SET sheet=" + sheet + " by=" + user + " name=" + person.name() + " period="
                            + first.name() + " amount=" + amount.toPlainString());
                }
            }
        }
        List<String> generated = periods.list(sheet).stream().map(Period::name)
                .filter((name) -> !year.before().contains(name)).toList();
        rollovers.keep(sheet, new Rollovers.Rollover(year.fy(), user, clock.today(sheet), generated, set));
        audit.record("ROLLOVER sheet=" + sheet + " by=" + user + " fy=" + year.fy() + " periods=" + made);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.pool.Pools;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Dated;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/**
 * Closes a period, fixing its due-total now, and each person's on the sheet (the part of it from their claims): the due now of the claims whose due-by falls in it
 * that counted at the end of its last day (OPEN, PENDING and SETTLED then by their status log, but not a deferred one, nor an unbound open one dated
 * within its person's hold) (a claim with no rate adds nothing); and each person's carried figure for it: the due now of
 * their claims that count at its end whose due-by falls in an earlier period (one ending before it starts) and that were
 * still OPEN or PENDING at its end by their status log, plus their opening balance for it; and every pool member's cut as it stands now. Shared by a close by hand and the auto close of a today change.
 */
@Service
public class PeriodCloser {

    private final Periods periods;
    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Settings settings;
    private final SheetClock clock;
    private final Audit audit;
    private final Pools pools;

    public PeriodCloser(Periods periods, Claims claims, People people, Rates rates, Settings settings, SheetClock clock,
            Audit audit, Pools pools) {
        this.pools = pools;
        this.periods = periods;
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.settings = settings;
        this.clock = clock;
        this.audit = audit;
    }

    /** Closes the period found open on the sheet; false when it was already closed. An auto close is audited auto=yes. */
    public boolean close(String sheet, String user, Period found, boolean auto) {
        return close(sheet, user, found, auto, false);
    }

    /**
     * Closes the period found open (or soft-closed) on the sheet, or soft-closes it, fixing its figures afresh; false
     * when it was already closed, or for a soft close already soft-closed.
     */
    public boolean close(String sheet, String user, Period found, boolean auto, boolean soft) {
        LocalDate from = LocalDate.parse(found.from());
        LocalDate to = LocalDate.parse(found.to());
        Map<Long, Person> byId = people.list(sheet).stream().collect(Collectors.toMap(Person::id, (p) -> p));
        List<Rate> sheetRates = rates.list(sheet);
        Dated floor = settings.floor(sheet);
        Late late = settings.late(sheet, clock.today(sheet));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        Map<Long, BigDecimal> perPerson = new LinkedHashMap<>();
        byId.keySet().forEach((id) -> perPerson.put(id, BigDecimal.ZERO.setScale(2)));
        Map<Long, BigDecimal> carried = new LinkedHashMap<>(perPerson);
        periods.openings(sheet, found.name()).forEach((id, amount) -> {
            if (carried.containsKey(id)) {
                carried.merge(id, amount, BigDecimal::add);
            }
        });
        List<Period> sheetPeriods = periods.list(sheet);
        List<Claim> sheetClaims = claims.list(sheet);
        for (Claim claim : sheetClaims) {
            Person person = byId.get(claim.person());
            LocalDate dueBy = LocalDate.parse(claim.dueBy());
            boolean earlier = sheetPeriods.stream().anyMatch((p) -> !dueBy.isBefore(LocalDate.parse(p.from()))
                    && !dueBy.isAfter(LocalDate.parse(p.to())) && LocalDate.parse(p.to()).isBefore(from));
            ClaimStatus then = claim.statusOn(to);
            if (person == null || !earlier || (then != ClaimStatus.OPEN && then != ClaimStatus.PENDING)
                    || !person.countsOn(claim, to)) {
                continue;
            }
            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
            if (due != null) {
                carried.merge(person.id(), due, BigDecimal::add);
            }
        }
        for (Claim claim : sheetClaims) {
            LocalDate date = LocalDate.parse(claim.dueBy());
            Person person = byId.get(claim.person());
            if (person == null || !person.countsOn(claim, to) || date.isBefore(from) || date.isAfter(to)) {
                continue;
            }
            BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
            if (due != null) {
                total = total.add(due);
                perPerson.merge(person.id(), due, BigDecimal::add);
            }
        }
        if (!periods.close(sheet, found.name(), total, perPerson, carried, soft)) {
            return false;
        }
        periods.fixPoolCuts(sheet, found.name(), pools.currentCuts(sheet));
        audit.record((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheet + " by=" + user + " period=" + found.name() + " total="
                + total.toPlainString() + (auto ? " auto=yes" : ""));
        return true;
    }

    /**
     * Closes, in order of their to-dates, every open (neither closed nor soft-closed) period of the sheet whose to-date plus the grace days is before
     * the sheet's today; none when the sheet has no grace days.
     */
    public void autoClose(String sheet, String user) {
        Integer grace = settings.graceDays(sheet);
        if (grace == null) {
            return;
        }
        LocalDate today = clock.today(sheet);
        List<Period> due = periods.list(sheet).stream()
                .filter((p) -> !p.fixed() && LocalDate.parse(p.to()).plusDays(grace).isBefore(today))
                .sorted(Comparator.comparing(Period::to)).toList();
        for (Period period : due) {
            close(sheet, user, period, true);
        }
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Undoes the sheet's last year end rollover: takes back the opening balances it set and removes the periods it
 * generated. Only the steward who made it may, on the same sheet-today it was made; refuses when there is none to
 * undo, or when a claim (of any status) is dated in a period it generated.
 */
public class UndoRollover {
    public void undo(@PathVariable("sheet") String sheet, @RequestParam("user") String user, Periods periods,
            Rollovers rollovers, Claims claims, Roles roles, SheetClock clock, Audit audit)
            throws InvalidPeriodException {
        if (!Role.STEWARD.equals(roles.of(sheet, user))) {
            throw new InvalidPeriodException("Only a steward may undo a rollover");
        }
        Rollovers.Rollover last = rollovers.last(sheet);
        if (last == null) {
            throw new InvalidPeriodException("There is no rollover to undo");
        }
        if (!last.by().equals(user)) {
            throw new InvalidPeriodException("Only the steward who made the rollover may undo it");
        }
        if (!last.on().equals(clock.today(sheet))) {
            throw new InvalidPeriodException("A rollover can only be undone on the day it was made");
        }
        List<Period> generated = periods.list(sheet).stream().filter((p) -> last.periods().contains(p.name()))
                .toList();
        for (Claim claim : claims.list(sheet)) {
            LocalDate date = LocalDate.parse(claim.date());
            for (Period period : generated) {
                if (!date.isBefore(LocalDate.parse(period.from())) && !date.isAfter(LocalDate.parse(period.to()))) {
                    throw new InvalidPeriodException("A claim belongs to the generated period " + period.name());
                }
            }
        }
        last.openings().forEach((o) -> periods.takeOpening(sheet, o.period(), o.person(), o.amount()));
        generated.forEach((p) -> periods.remove(sheet, p.name()));
        rollovers.forget(sheet);
        audit.record("ROLLOVER_UNDONE sheet=" + sheet + " by=" + user + " fy=" + last.fy());
    }
}
